 @Override public void onCreate(Bundle b){super.onCreate(b);d=getResources().getDisplayMetrics().density;ar="ar".equals(getResources().getConfiguration().locale.getLanguage());place=WeatherService.getSavedLocation(this);getWindow().setFlags(1024,1024);getWindow().setBackgroundDrawable(new ColorDrawable(0xff080d19));try{latin=Typeface.createFromAsset(getAssets(),"fonts/InterDisplay-Medium.otf");}catch(Exception e){latin=Typeface.DEFAULT_BOLD;}try{arab=Typeface.createFromAsset(getAssets(),"fonts/NotoKufiArabic-Regular.ttf");}catch(Exception e){arab=Typeface.DEFAULT;}try{icons=Typeface.createFromAsset(getAssets(),"fonts/weathericons-regular-webfont.ttf");}catch(Exception e){icons=Typeface.DEFAULT;}build();load();}
 int dp(float x){return (int)(x*d+.5f);}String t(String en,String a){return ar?a:en;}
