 void section(LinearLayout parent,String s){TextView v=text(s,16,-1,true);v.setPadding(dp(3),dp(16),dp(3),dp(7));parent.addView(v);}
 void load(){if(busy||dead)return;busy=true;place=WeatherService.getSavedLocation(this);if(loc!=null)loc.setText(place.shortName()+" ▾");status.setText(t("Updating…","جارٍ التحديث…"));final WeatherService.Place p=place;
  new AsyncTask<Void,Void,JSONObject>(){protected JSONObject doInBackground(Void...v){try{return WeatherService.fetchForecast(p.latitude,p.longitude);}catch(Exception e){return null;}}
  protected void onPostExecute(JSONObject j){busy=false;if(dead||isFinishing())return;if(j==null){status.setText(t("Weather unavailable. Check Internet and retry.","الطقس غير متاح. تحقق من الإنترنت وأعد المحاولة."));return;}try{render(j,p);status.setText("");}catch(Exception e){status.setText(t("Could not read forecast.","تعذرت قراءة التوقعات."));}}}.executeOnExecutor(AsyncTask.THREAD_POOL_EXECUTOR);}
 String deg(double n){return Double.isNaN(n)?"--°":Math.round(n)+"°";}String hh(String s){return s!=null&&s.length()>=16?s.substring(11,16):"--";}
 void render(JSONObject j,WeatherService.Place p)throws Exception{
  JSONObject c=j.getJSONObject("current"),day=j.getJSONObject("daily");int code=c.optInt("weather_code",-1);double n=c.optDouble("temperature_2m",Double.NaN);city.setText(p.name);temp.setText(deg(n));cond.setText(WeatherService.condition(code,ar));glyph.setText(WeatherService.icon(code,c.optInt("is_day",1)==1));feels.setText(t("Feels like ","المحسوسة ")+deg(c.optDouble("apparent_temperature",n)));
  JSONArray hi=day.optJSONArray("temperature_2m_max"),lo=day.optJSONArray("temperature_2m_min");range.setText(t("High ","العظمى ")+deg(hi==null?Double.NaN:hi.optDouble(0,Double.NaN))+"  "+t("Low ","الصغرى ")+deg(lo==null?Double.NaN:lo.optDouble(0,Double.NaN)));
  String stamp=c.optString("time","");updated.setText(t("Updated ","آخر تحديث ")+hh(stamp)+" · "+p.name);metrics.removeAllViews();
  metric(t("Humidity","الرطوبة"),c.optInt("relative_humidity_2m",-1)+"%",t("Relative humidity","الرطوبة النسبية"));
  metric(t("Wind","الرياح"),Math.round(c.optDouble("wind_speed_10m",0))+" km/h",WeatherService.windDirection(c.optInt("wind_direction_10m",0),ar));
  JSONArray rain=day.optJSONArray("precipitation_probability_max");metric(t("Rain chance","احتمال المطر"),rain==null?"--":rain.optInt(0,-1)+"%",t("Today","اليوم"));
  JSONArray uv=day.optJSONArray("uv_index_max");double u=uv==null?Double.NaN:uv.optDouble(0,Double.NaN);metric(t("UV index","الأشعة فوق البنفسجية"),Double.isNaN(u)?"--":String.format(Locale.US,"%.1f",u),u<3?t("Low","منخفض"):u<6?t("Moderate","متوسط"):u<8?t("High","مرتفع"):t("Very high","مرتفع جداً"));
  renderHours(j.getJSONObject("hourly"),stamp);renderDays(day);renderSun(day);
 }
 void metric(String n,String v,String sub){LinearLayout b=box(true);b.setPadding(dp(8),dp(8),dp(8),dp(6));b.setBackground(shape(0xff111a2b,0xff26334a,12));b.addView(text(n,10,0xffaebbd0,false));TextView x=text(v,17,-1,true);x.setTextDirection(3);b.addView(x);b.addView(text(sub,9,0xff8795ac,false));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,-1,1);p.setMargins(dp(3),0,dp(3),0);metrics.addView(b,p);}
 void renderHours(JSONObject j,String stamp){hours.removeAllViews();JSONArray ts=j.optJSONArray("time"),vs=j.optJSONArray("temperature_2m"),cs=j.optJSONArray("weather_code"),rs=j.optJSONArray("precipitation_probability");if(ts==null||vs==null||cs==null)return;int start=0;for(int i=0;i<ts.length();i++)if(ts.optString(i,"").compareTo(stamp)>=0){start=i;break;}for(int i=start;i<Math.min(ts.length(),start+12);i++){LinearLayout b=box(true);b.setGravity(Gravity.CENTER);b.setPadding(dp(7),dp(7),dp(7),dp(7));b.setBackground(shape(0xff111a2b,0xff26334a,11));b.addView(text(i==start?t("Now","الآن"):hh(ts.optString(i,"")),10,0xffb7c3d8,false));TextView ic=text(WeatherService.icon(cs.optInt(i,-1),true),23,0xffffd27a,true);ic.setTypeface(icons);ic.setGravity(Gravity.CENTER);b.addView(ic);b.addView(text(deg(vs.optDouble(i,Double.NaN)),15,-1,true));b.addView(text(rs==null?"--":rs.optInt(i,-1)+"%",9,0xff81c5ff,false));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(dp(78),-2);p.setMargins(dp(3),0,dp(3),0);hours.addView(b,p);}}
 void renderDays(JSONObject j){days.removeAllViews();JSONArray ts=j.optJSONArray("time"),cs=j.optJSONArray("weather_code"),hi=j.optJSONArray("temperature_2m_max"),lo=j.optJSONArray("temperature_2m_min"),rain=j.optJSONArray("precipitation_probability_max");if(ts==null||cs==null||hi==null||lo==null)return;for(int i=0;i<Math.min(7,ts.length());i++){LinearLayout r=box(false);r.setGravity(Gravity.CENTER_VERTICAL);r.addView(text(dayName(ts.optString(i,""),i),12,-1,true),new LinearLayout.LayoutParams(dp(94),dp(34)));TextView ic=text(WeatherService.icon(cs.optInt(i,-1),true),22,0xffffd27a,true);ic.setTypeface(icons);ic.setGravity(Gravity.CENTER);r.addView(ic,new LinearLayout.LayoutParams(dp(44),dp(34)));r.addView(text(rain==null?"":rain.optInt(i,-1)+"%",9,0xff81c5ff,false),new LinearLayout.LayoutParams(dp(40),dp(34)));TextView temps=text(deg(lo.optDouble(i,Double.NaN))+"   "+deg(hi.optDouble(i,Double.NaN)),13,-1,true);temps.setTextDirection(3);temps.setGravity(Gravity.END|Gravity.CENTER_VERTICAL);r.addView(temps,new LinearLayout.LayoutParams(0,dp(34),1));days.addView(r);if(i<6){View line=new View(this);line.setBackgroundColor(0x222f405a);days.addView(line,new LinearLayout.LayoutParams(-1,dp(1)));}}}
 void renderSun(JSONObject j){sun.removeAllViews();JSONArray rise=j.optJSONArray("sunrise"),set=j.optJSONArray("sunset");sun.addView(sunValue(t("Sunrise","الشروق"),rise==null?"--":hh(rise.optString(0,"")),0xffffc978),new LinearLayout.LayoutParams(0,-1,1));View line=new View(this);line.setBackgroundColor(0x335a6a82);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(dp(1),-1);p.leftMargin=dp(16);p.rightMargin=dp(16);sun.addView(line,p);sun.addView(sunValue(t("Sunset","الغروب"),set==null?"--":hh(set.optString(0,"")),0xffffa56d),new LinearLayout.LayoutParams(0,-1,1));}
 LinearLayout sunValue(String n,String v,int color){LinearLayout b=box(true);b.setGravity(Gravity.CENTER);b.addView(text(n,10,0xff9baac0,false));TextView x=text(v,17,color,true);x.setTextDirection(3);b.addView(x);return b;}
 void chooseCity(){final Dialog dialog=new Dialog(this);dialog.requestWindowFeature(Window.FEATURE_NO_TITLE);LinearLayout b=box(true);b.setPadding(dp(16),dp(14),dp(16),dp(14));b.setBackground(shape(0xff111a2b,0xff45536a,16));b.addView(text(t("Choose a city","اختر مدينة"),17,-1,true));final EditText q=new EditText(this);q.setSingleLine(true);q.setTextColor(-1);q.setHintTextColor(0xff9baac0);q.setHint(t("Search city","ابحث عن مدينة"));q.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_FLAG_CAP_WORDS);q.setBackground(shape(0xff202b40,0xff45536a,10));LinearLayout.LayoutParams qp=new LinearLayout.LayoutParams(-1,dp(44));qp.topMargin=dp(10);b.addView(q,qp);TextView search=button(t("Search","بحث"),null);LinearLayout.LayoutParams sp=new LinearLayout.LayoutParams(-1,dp(40));sp.topMargin=dp(7);b.addView(search,sp);final TextView msg=text("",10,0xffffc978,false);b.addView(msg);ScrollView sc=new ScrollView(this);final LinearLayout results=box(true);sc.addView(results);b.addView(sc,new LinearLayout.LayoutParams(-1,dp(190)));search.setOnClickListener(v->{final String query=q.getText().toString().trim();if(query.length()<2){msg.setText(t("Type at least two letters","اكتب حرفين على الأقل"));return;}msg.setText(t("Searching…","جارٍ البحث…"));new AsyncTask<Void,Void,List<WeatherService.Place>>(){protected List<WeatherService.Place> doInBackground(Void...z){try{return WeatherService.searchLocations(query,ar);}catch(Exception e){return null;}}protected void onPostExecute(List<WeatherService.Place> found){if(dead||isFinishing())return;results.removeAllViews();if(found==null||found.isEmpty()){msg.setText(t("No results","لا توجد نتائج"));return;}msg.setText(t("Select location","اختر الموقع"));for(final WeatherService.Place p:found){TextView item=button(p.name,()->{getSharedPreferences(WeatherService.PREFS,0).edit().putString(WeatherService.PREF_CITY,p.name).putFloat(WeatherService.PREF_LATITUDE,(float)p.latitude).putFloat(WeatherService.PREF_LONGITUDE,(float)p.longitude).apply();place=p;dialog.dismiss();load();});LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,dp(38));lp.topMargin=dp(3);results.addView(item,lp);}}}.executeOnExecutor(AsyncTask.THREAD_POOL_EXECUTOR);});dialog.setContentView(b);dialog.show();Window w=dialog.getWindow();if(w!=null){w.setBackgroundDrawable(new ColorDrawable(Color.TRANSPARENT));WindowManager.LayoutParams p=w.getAttributes();p.width=Math.min(dp(560),(int)(getResources().getDisplayMetrics().widthPixels*.7f));p.height=-2;p.gravity=Gravity.CENTER;w.setAttributes(p);}q.requestFocus();}
 String dayName(String date,int i){if(i==0)return t("Today","اليوم");if(i==1)return t("Tomorrow","غداً");try{return new SimpleDateFormat("EEE",getResources().getConfiguration().locale).format(new SimpleDateFormat("yyyy-MM-dd",Locale.US).parse(date));}catch(Exception e){return date;}}
 String uvLabel(double v){if(Double.isNaN(v))return t("UV exposure","مستوى الأشعة");if(v<3)return t("Low","منخفض");if(v<6)return t("Moderate","متوسط");if(v<8)return t("High","مرتفع");if(v<11)return t("Very high","مرتفع جداً");return t("Extreme","شديد");}
